bool checkUserPassword(std::string& user_password, const std::string& owner_password, const QPDF::EncryptionData& data) {
    // Compute the RC4 key based on user and owner passwords
    std::string rc4_key;
    {
        std::string password = user_password;
        if (owner_password != "") {
            password = owner_password;
        }

        // Initialize MD5 context
        MD5_CTX context;
        MD5_Init(&context);
        MD5_Update(&context, password.c_str(), password.length());
        unsigned char md5_digest[MD5_DIGEST_LENGTH];
        MD5_Final(md5_digest, &context);

        // Convert MD5 digest to string
        rc4_key.resize(MD5_DIGEST_LENGTH);
        std::memcpy(&rc4_key[0], md5_digest, MD5_DIGEST_LENGTH);
    }

    // Retrieve the O data from encryption data
    std::string O = data.getO();

    // Initialize RC4 state
    std::vector<unsigned char> state(256);
    for (int i = 0; i < 256; ++i) {
        state[i] = i;
    }

    int j = 0;
    for (int i = 0; i < 256; ++i) {
        j = (j + state[i] + rc4_key[i % rc4_key.size()]) % 256;
        std::swap(state[i], state[j]);
    }

    // Generate new user password using RC4 algorithm
    std::string new_user_password;
    for (char c : O) {
        int i = 0;
        i = (i + 1) % 256;
        j = (j + state[i]) % 256;
        std::swap(state[i], state[j]);
        int k = (state[i] + state[j]) % 256;
        new_user_password += c ^ state[k];
    }

    // Check if the new user password matches the provided data
    if (new_user_password == data.getUserPassword()) {
        user_password = new_user_password;
        return true;
    }

    return false;
}
